WITH unpacked AS (SELECT id, plan, currency, tier_prices, discounts, ELEMENT_AT(tier_prices, 1) AS entry_price, TRANSFORM(tier_prices, (p, i) -> ROUND(p * tier_limits[i], 2)) AS tier_revenue_caps FROM price_tiers WHERE plan IN ('starter', 'enterprise', 'pro')) SELECT plan, COUNT_IF(plan = 'pro') AS pro_events, COUNT_IF(currency = 'USD') AS usd_events, COUNT(*) FILTER (WHERE plan = 'enterprise') AS enterprise_rows, AVG(entry_price) FILTER (WHERE plan = 'pro') AS pro_avg_entry_price, SIZE(COLLECT_SET(currency)) AS num_currencies FROM unpacked GROUP BY plan HAVING num_currencies >= 1
